#include "editor/SubspaceEditorAcceptanceSystem.h"
namespace subspace {EditorWorkspaceRegistry SubspaceEditorAcceptanceSystem::BuildDefaultWorkspaceRegistry(){EditorWorkspaceRegistry r;r.Register({EditorWorkspaceKind::Shipyard,"shipyard","Shipyard","Build, refit, appearance, systems, and advanced module authoring.",true,true});r.Register({EditorWorkspaceKind::StationBuilder,"station","Station Builder","Assemble orbital stations from certified modular kits.",true,true});r.Register({EditorWorkspaceKind::TurretLab,"turret","Turret Lab","Author turret bases, housings, weapons, and sensors.",false,true});r.Register({EditorWorkspaceKind::PlanetSector,"planet","Planet / Sector","Author planetary hex-sector structures and strategic content.",false,true});r.Register({EditorWorkspaceKind::MaterialStudio,"materials","Material Studio","Normalize surfaces, liveries, patterns, and decals.",false,true});r.Register({EditorWorkspaceKind::PcgStudio,"pcg","PCG Studio","DesignDNA, exemplars, faction/manufacturer grammar, and validation.",false,true});r.Register({EditorWorkspaceKind::BlueprintLibrary,"blueprints","Blueprint Library","Browse reusable ships, stations, turrets, and construction templates.",true,true});return r;}EditorAcceptanceResult SubspaceEditorAcceptanceSystem::ValidateProjectWideEditor(const EditorWorkspaceRegistry&r,bool theme,bool help,bool browser,bool place,bool commands,bool selection){EditorAcceptanceResult o;auto req=[&](bool ok,const char*m){if(!ok)o.failures.push_back(m);};req(r.Find(EditorWorkspaceKind::Shipyard),"Shipyard workspace missing");req(r.Find(EditorWorkspaceKind::StationBuilder),"Station workspace missing");req(r.Find(EditorWorkspaceKind::TurretLab),"Turret workspace missing");req(r.Find(EditorWorkspaceKind::MaterialStudio),"Material Studio missing");req(r.Find(EditorWorkspaceKind::PcgStudio),"PCG Studio missing");req(theme,"Shared UI theme authority missing");req(help,"Shared help registry missing");req(browser,"Universal asset browser missing");req(place,"Universal placement resolver missing");req(commands,"Global command stack missing");req(selection,"Global selection service missing");o.passed=o.failures.empty();return o;}}
